17	/** A class for interfacing with Flickr's http API. */
18	public final class Api {
19	  private static Api api;
20	  private static final String API_KEY = "f0e6fbb5fdf1f3842294a1d21f84e8a6";
21	  private static final String SIGNED_API_URL =
22	      "https://api.flickr.com/services/rest/?method=%s&format=json&api_key=" + API_KEY;
23	  // Incomplete size independent url for photos that can be cached per photo
24	  private static final String CACHEABLE_PHOTO_URL = "http://farm%s.staticflickr.com/%s/%s_%s_";
25	  private static final int MAX_URLS_TO_CACHE = 2000;
26	  private static final LruCache<UrlCacheKey, String> CACHED_URLS =
27	      new LruCache<>(MAX_URLS_TO_CACHE);
28	  private static final int MAX_ITEMS_PER_PAGE = 300;
29	
30	  /**
31	   * Safe search is on by default in Flickr's API and/or enabling it isn't very effective. Instead
32	   * we'll force all images to be from Flickr's commons project, which tends to be historic images.
33	   * Those appear much safer than a standard search.
34	   */
35	  private static final String SAFE_SEARCH = "&is_commons=1";
36	
37	  private static final String PER_PAGE = "&per_page=" + MAX_ITEMS_PER_PAGE;
38	
39	  private static final SparseArray<String> EDGE_TO_SIZE_KEY =
40	      new SparseArray<String>() {
41	        {
42	          put(75, "s");
43	          put(100, "t");
44	          put(150, "q");
45	          put(240, "m");
46	          put(320, "n");
47	          put(640, "z");
48	          put(1024, "b");
49	        }
50	      };
51	  private static final List<Integer> SORTED_SIZE_KEYS = new ArrayList<>(EDGE_TO_SIZE_KEY.size());
52	
53	  static {
54	    for (int i = 0; i < EDGE_TO_SIZE_KEY.size(); i++) {
55	      SORTED_SIZE_KEYS.add(EDGE_TO_SIZE_KEY.keyAt(i));
56	    }
57	    Collections.sort(SORTED_SIZE_KEYS);
58	  }
59	
60	  public static final int SQUARE_THUMB_SIZE = SORTED_SIZE_KEYS.get(0);
61	
62	  private static String getSizeKey(int width, int height) {
63	    final int largestEdge = Math.max(width, height);
64	
65	    String result = EDGE_TO_SIZE_KEY.get(SORTED_SIZE_KEYS.get(SORTED_SIZE_KEYS.size() - 1));
66	    for (int edge : SORTED_SIZE_KEYS) {
67	      if (largestEdge <= edge) {
68	        result = EDGE_TO_SIZE_KEY.get(edge);
69	        break;
70	      }
71	    }
72	    return result;
73	  }
74	
75	  private static List<String> getLargerSizeKeys(int width, int height) {
76	    final int largestEdge = Math.max(width, height);
77	
78	    boolean isFirstLargest = true;
79	    List<String> result = new ArrayList<>();
80	    int size = SORTED_SIZE_KEYS.size();
81	    for (int i = 0; i < size; i++) {
82	      int edge = SORTED_SIZE_KEYS.get(i);
83	      if (largestEdge <= edge) {
84	        if (isFirstLargest) {
85	          isFirstLargest = false;
86	        } else {
87	          result.add(EDGE_TO_SIZE_KEY.get(edge));
88	        }
89	      }
90	    }
91	    return result;
92	  }
93	
94	  static String getCacheableUrl(Photo photo) {
95	    return String.format(
96	        CACHEABLE_PHOTO_URL, photo.getFarm(), photo.getServer(), photo.getId(), photo.getSecret());
97	  }
98	
99	  public static String getPhotoURL(Photo photo, int width, int height) {
100	    return getPhotoUrl(photo, getSizeKey(width, height));
101	  }
102	
103	  public static List<String> getAlternateUrls(Photo photo, int width, int height) {
104	    List<String> result = new ArrayList<>();
105	    for (String sizeKey : getLargerSizeKeys(width, height)) {
106	      result.add(getPhotoUrl(photo, sizeKey));
107	    }
108	    return result;
109	  }
110	
111	  private static String getUrlForMethod(String method) {
112	    return String.format(SIGNED_API_URL, method);
113	  }
114	
115	  private static String getPhotoUrl(Photo photo, String sizeKey) {
116	    UrlCacheKey entry = new UrlCacheKey(photo, sizeKey);
117	    String result = CACHED_URLS.get(entry);
118	    if (result == null) {
119	      result = photo.getPartialUrl() + sizeKey + ".jpg";
120	      CACHED_URLS.put(entry, result);
121	    }
122	    return result;
123	  }
124	
125	  static String getSearchUrl(String text, boolean requireSafeOverQuality) {
126	    return getUrlForMethod("flickr.photos.search")
127	        + "&text="
128	        + text
129	        + PER_PAGE
130	        + (requireSafeOverQuality ? SAFE_SEARCH : "");
131	  }
132	
133	  static String getRecentUrl() {
134	    return getUrlForMethod("flickr.photos.getRecent" + PER_PAGE);
135	  }
