137	  /** An interface for listening for search results from the Flickr API. */
138	  public interface QueryListener {
139	    /**
140	     * Called when a search completes successfully.
141	     *
142	     * @param query The query used to obtain the results.
143	     * @param photos A list of images that were found for the given search term.
144	     */
145	    void onSearchCompleted(Query query, List<Photo> photos);
146	
147	    /**
148	     * Called when a search fails.
149	     *
150	     * @param query The query we attempted to obtain results for.
151	     * @param e The exception that caused the search to fail.
152	     */
153	    void onSearchFailed(Query query, Exception e);
154	  }
155	
156	  public static Api get(Context context) {
157	    if (api == null) {
158	      api = new Api(context);
159	    }
160	    return api;
161	  }
162	
163	  private final RequestQueue requestQueue;
164	  private final Set<QueryListener> queryListeners = new HashSet<>();
165	  private QueryResult lastQueryResult;
166	
167	  private Api(Context context) {
168	    this.requestQueue = Volley.newRequestQueue(context.getApplicationContext());
169	    QueryListener queryListener =
170	        new QueryListener() {
171	          @Override
172	          public void onSearchCompleted(Query query, List<Photo> photos) {
173	            lastQueryResult = new QueryResult(query, photos);
174	          }
175	
176	          @Override
177	          public void onSearchFailed(Query query, Exception e) {
178	            lastQueryResult = null;
179	          }
180	        };
181	    queryListeners.add(queryListener);
182	  }
183	
184	  public void registerSearchListener(QueryListener queryListener) {
185	    queryListeners.add(queryListener);
186	  }
187	
188	  public void unregisterSearchListener(QueryListener queryListener) {
189	    queryListeners.remove(queryListener);
190	  }
191	
192	  public void query(Query query) {
193	    if (lastQueryResult != null && lastQueryResult.query.equals(query)) {
194	      for (QueryListener listener : queryListeners) {
195	        listener.onSearchCompleted(lastQueryResult.query, lastQueryResult.results);
196	      }
197	      return;
198	    }
199	
200	    FlickrQueryResponseListener responseListener =
201	        new FlickrQueryResponseListener(new PhotoJsonStringParser(), query, queryListeners);
202	    StringRequest request =
203	        new StringRequest(Request.Method.GET, query.getUrl(), responseListener, responseListener);
204	    request.setRetryPolicy(
205	        new DefaultRetryPolicy(
206	            DefaultRetryPolicy.DEFAULT_TIMEOUT_MS, 3, DefaultRetryPolicy.DEFAULT_BACKOFF_MULT));
207	    requestQueue.add(request);
208	  }
209	
210	  private static class QueryResult {
211	    private final Query query;
212	    private final List<Photo> results;
213	
214	    QueryResult(Query query, List<Photo> results) {
215	      this.query = query;
216	      this.results = results;
217	    }
218	  }
219	
220	  private static final class UrlCacheKey {
221	    private final Photo photo;
222	    private final String sizeKey;
223	
224	    private UrlCacheKey(Photo photo, String sizeKey) {
225	      this.photo = photo;
226	      this.sizeKey = sizeKey;
227	    }
228	
229	    @Override
230	    public boolean equals(Object o) {
231	      if (o instanceof UrlCacheKey) {
232	        UrlCacheKey other = (UrlCacheKey) o;
233	        return photo.equals(other.photo) && sizeKey.equals(other.sizeKey);
234	      }
235	      return false;
236	    }
237	
238	    @Override
239	    public int hashCode() {
240	      int result = photo.hashCode();
241	      result = 31 * result + sizeKey.hashCode();
242	      return result;
243	    }
244	  }
245	}
