192	  private void executeQuery(Query query) {
193	    currentQuery = query;
194	    if (query == null) {
195	      queryListener.onSearchCompleted(null, Collections.<Photo>emptyList());
196	      return;
197	    }
198	
199	    searching.setVisibility(View.VISIBLE);
200	    searchLoading.setVisibility(View.VISIBLE);
201	    searchTerm.setText(getString(R.string.searching_for, currentQuery.getDescription()));
