206	  private class QueryListener implements Api.QueryListener {
207	    @Override
208	    public void onSearchCompleted(Query query, List<Photo> photos) {
209	      if (!isCurrentQuery(query)) {
210	        return;
211	      }
212	
213	      if (Log.isLoggable(TAG, Log.DEBUG)) {
214	        Log.d(TAG, "Search completed, got " + photos.size() + " results");
215	      }
216	      searching.setVisibility(View.INVISIBLE);
217	
218	      for (PhotoViewer viewer : photoViewers) {
219	        viewer.onPhotosUpdated(photos);
220	      }
221	
222	      if (backgroundThumbnailFetcher != null) {
223	        backgroundThumbnailFetcher.cancel();
224	      }
225	
226	      backgroundThumbnailFetcher =
227	          new BackgroundThumbnailFetcher(FlickrSearchActivity.this, photos);
228	      backgroundHandler.post(backgroundThumbnailFetcher);
229	
230	      currentPhotos = photos;
231	    }
232	
233	    private boolean isCurrentQuery(Query query) {
234	      return currentQuery != null && currentQuery.equals(query);
235	    }
236	
237	    @Override
238	    public void onSearchFailed(Query query, Exception e) {
239	      if (!isCurrentQuery(query)) {
240	        return;
241	      }
242	
243	      if (Log.isLoggable(TAG, Log.ERROR)) {
244	        Log.e(TAG, "Search failed", e);
245	      }
246	      searching.setVisibility(View.VISIBLE);
247	      searchLoading.setVisibility(View.INVISIBLE);
248	      searchTerm.setText(getString(R.string.search_failed, currentQuery.getDescription()));
249	    }
250	  }
