314	  private static class BackgroundThumbnailFetcher implements Runnable {
315	    private final Context context;
316	    private final List<Photo> photos;
317	
318	    private boolean isCancelled;
319	
320	    BackgroundThumbnailFetcher(Context context, List<Photo> photos) {
321	      this.context = context;
322	      this.photos = photos;
323	    }
324	
325	    void cancel() {
326	      isCancelled = true;
327	    }
328	
329	    @Override
330	    public void run() {
331	      Process.setThreadPriority(Process.THREAD_PRIORITY_LOWEST);
332	      for (Photo photo : photos) {
333	        if (isCancelled) {
334	          return;
335	        }
336	
337	        FutureTarget<File> futureTarget =
338	            GlideApp.with(context)
339	                .downloadOnly()
340	                .load(photo)
341	                .submit(Api.SQUARE_THUMB_SIZE, Api.SQUARE_THUMB_SIZE);
342	
343	        try {
344	          futureTarget.get();
345	        } catch (InterruptedException e) {
346	          if (Log.isLoggable(TAG, Log.DEBUG)) {
347	            Log.d(TAG, "Interrupted waiting for background downloadOnly", e);
348	          }
349	        } catch (ExecutionException e) {
350	          if (Log.isLoggable(TAG, Log.DEBUG)) {
351	            Log.d(TAG, "Got ExecutionException waiting for background downloadOnly", e);
352	          }
353	        }
354	        GlideApp.with(context).clear(futureTarget);
355	      }
356	    }
357	  }
358	}
