16	
17	/** A java wrapper for Giphy's http api based on https://github.com/Giphy/GiphyAPI. */
18	public final class Api {
19	  private static volatile Api api = null;
20	  private static final String BETA_KEY = "dc6zaTOxFJmzC";
21	  private static final String BASE_URL = "https://api.giphy.com/";
22	  private static final String TRENDING_PATH = "v1/gifs/trending";
23	  private static final int LIMIT = 100;
24	  private static final int OFFSET = 0;
25	  private final Handler bgHandler;
26	  private final Handler mainHandler;
27	  private final HashSet<Monitor> monitors = new HashSet<>();
28	
29	  private static String signUrl(String url) {
30	    return url + "&api_key=" + BETA_KEY;
31	  }
32	
33	  private static String getTrendingUrl() {
34	    return signUrl(BASE_URL + TRENDING_PATH + "?limit=" + LIMIT + "&offset=" + OFFSET);
35	  }
36	
37	  /** An interface for listening for search results. */
38	  public interface Monitor {
39	    /**
40	     * Called when a search completes.
41	     *
42	     * @param result The results returned from Giphy's search api.
43	     */
44	    void onSearchComplete(SearchResult result);
45	  }
46	
47	  static Api get() {
48	    if (api == null) {
49	      synchronized (Api.class) {
50	        if (api == null) {
51	          api = new Api();
52	        }
53	      }
54	    }
55	    return api;
56	  }
57	
58	  private Api() {
59	    HandlerThread bgThread = new HandlerThread("api_thread");
60	    bgThread.start();
61	    bgHandler = new Handler(bgThread.getLooper());
62	    mainHandler = new Handler(Looper.getMainLooper());
63	    // Do nothing.
64	  }
65	
66	  void addMonitor(Monitor monitor) {
67	    monitors.add(monitor);
68	  }
69	
70	  void removeMonitor(Monitor monitor) {
71	    monitors.remove(monitor);
72	  }
73	
74	  void getTrending() {
75	    String trendingUrl = getTrendingUrl();
76	    query(trendingUrl);
77	  }
78	
79	  private void query(final String apiUrl) {
80	    bgHandler.post(
81	        new Runnable() {
82	          @Override
83	          public void run() {
84	            URL url;
85	            try {
86	              url = new URL(apiUrl);
87	            } catch (MalformedURLException e) {
88	              throw new RuntimeException(e);
89	            }
90	
91	            HttpURLConnection urlConnection = null;
92	            InputStream is = null;
93	            SearchResult result = new SearchResult();
94	            try {
95	              urlConnection = (HttpURLConnection) url.openConnection();
96	              is = urlConnection.getInputStream();
97	              InputStreamReader reader = new InputStreamReader(is);
98	              result = new Gson().fromJson(reader, SearchResult.class);
99	            } catch (IOException e) {
100	              e.printStackTrace();
101	            } finally {
102	              if (is != null) {
103	                try {
104	                  is.close();
105	                } catch (IOException e) {
106	                  // Do nothing.
107	                }
108	              }
109	              if (urlConnection != null) {
110	                urlConnection.disconnect();
111	              }
112	            }
113	
114	            final SearchResult finalResult = result;
115	            mainHandler.post(
116	                new Runnable() {
117	                  @Override
118	                  public void run() {
119	                    for (Monitor monitor : monitors) {
120	                      monitor.onSearchComplete(finalResult);
121	                    }
122	                  }
123	                });
124	          }
125	        });
126	  }
127	
128	  /** A POJO mirroring the top level result JSON object returned from Giphy's api. */
129	  public static final class SearchResult {
130	    public GifResult[] data;
131	
132	    @Override
133	    public String toString() {
134	      return "SearchResult{" + "data=" + Arrays.toString(data) + '}';
135	    }
136	  }
137	
138	  /**
139	   * A POJO mirroring an individual GIF image returned from Giphy's api.
140	   *
141	   * <p>Implements equals and hashcode so that in memory caching will work when this object is used
142	   * as a model for loading Glide's images.
143	   */
144	  public static final class GifResult {
145	    public String id;
146	    GifUrlSet images;
147	
148	    @Override
149	    public int hashCode() {
150	      int result = id != null ? id.hashCode() : 17;
151	      result = 31 * result + (images != null ? images.hashCode() : 17);
152	      return result;
153	    }
154	
155	    @Override
156	    public boolean equals(Object obj) {
157	      if (obj instanceof GifResult) {
158	        GifResult other = (GifResult) obj;
159	        return Util.bothNullOrEqual(id, other.id) && Util.bothNullOrEqual(images, other.images);
160	      }
161	      return false;
162	    }
163	
164	    @Override
165	    public String toString() {
166	      return "GifResult{" + "id='" + id + '\'' + ", images=" + images + '}';
167	    }
168	  }
169	
170	  /**
171	   * A POJO mirroring a JSON object with a put of urls of different sizes and dimensions returned
172	   * for a single image from Giphy's api.
173	   */
174	  public static final class GifUrlSet {
175	    GifImage original;
176	    GifImage fixed_width;
177	    GifImage fixed_height;
178	
179	    @Override
180	    public int hashCode() {
181	      int result = original != null ? original.hashCode() : 17;
182	      result = 31 * result + (fixed_width != null ? fixed_width.hashCode() : 17);
183	      result = 31 * result + (fixed_height != null ? fixed_height.hashCode() : 17);
184	      return result;
185	    }
186	
187	    @Override
188	    public boolean equals(Object obj) {
189	      if (obj instanceof GifUrlSet) {
190	        GifUrlSet other = (GifUrlSet) obj;
191	        return Util.bothNullOrEqual(original, other.original)
192	            && Util.bothNullOrEqual(fixed_width, other.fixed_width)
193	            && Util.bothNullOrEqual(fixed_height, other.fixed_height);
194	      }
195	      return false;
196	    }
197	
198	    @Override
199	    public String toString() {
200	      return "GifUrlSet{"
201	          + "original="
202	          + original
203	          + ", fixed_width="
204	          + fixed_width
205	          + ", fixed_height="
206	          + fixed_height
207	          + '}';
208	    }
209	  }
210	
211	  /**
212	   * A POJO mirroring a JSON object for an image with one particular url, size and dimension
213	   * returned from Giphy's api.
214	   */
215	  public static final class GifImage {
216	    String url;
217	    int width;
218	    int height;
219	
220	    @Override
221	    public int hashCode() {
222	      int result = url != null ? url.hashCode() : 17;
223	      result = 31 * result + width;
