233	            && other.height == height
234	            && Util.bothNullOrEqual(url, other.url);
235	      }
236	      return false;
237	    }
238	
239	    public String toString() {
240	      return "GifImage{" + "url='" + url + '\'' + ", width=" + width + ", height=" + height + '}';
241	    }
242	  }
