1	package com.bumptech.glide.samples.imgur.api;
2	
3	import java.util.ArrayList;
4	import java.util.Iterator;
5	import java.util.List;
6	import rx.Observable;
7	import rx.functions.Func1;
8	import rx.functions.Func2;
9	
10	/** Observables for retrieving metadata from Imgur's API. */
11	final class ImgurObservables {
12	
13	  private final ImgurService imgurService;
14	
15	  ImgurObservables(ImgurService imgurService) {
16	    this.imgurService = imgurService;
17	  }
18	
19	  Observable<List<Image>> getHotViralImages(@SuppressWarnings("SameParameterValue") int maxPages) {
20	    return Observable.range(0, maxPages)
21	        .flatMap(
22	            new Func1<Integer, Observable<List<Image>>>() {
23	              @Override
24	              public Observable<List<Image>> call(Integer integer) {
25	                return imgurService
26	                    .getHotViral(integer)
27	                    .map(new GetData())
28	                    .flatMap(
29	                        new Func1<List<Image>, Observable<List<Image>>>() {
30	                          @Override
31	                          public Observable<List<Image>> call(List<Image> images) {
32	                            for (Iterator<Image> iterator = images.iterator();
33	                                iterator.hasNext(); ) {
34	                              if (iterator.next().is_album) {
35	                                iterator.remove();
36	                              }
37	                            }
38	                            return Observable.just(images);
39	                          }
40	                        });
41	              }
42	            })
43	        .takeWhile(
44	            new Func1<List<Image>, Boolean>() {
45	              @Override
46	              public Boolean call(List<Image> images) {
47	                return !images.isEmpty();
48	              }
49	            })
50	        .scan(
51	            new Func2<List<Image>, List<Image>, List<Image>>() {
52	              @Override
53	              public List<Image> call(List<Image> images, List<Image> images2) {
54	                List<Image> result = new ArrayList<>(images.size() + images2.size());
55	                result.addAll(images);
56	                result.addAll(images2);
57	                return result;
58	              }
59	            })
60	        .cache();
61	  }
62	
63	  private static class GetData implements Func1<Gallery, List<Image>> {
64	    @Override
65	    public List<Image> call(Gallery gallery) {
66	      return gallery.data;
67	    }
68	  }
69	}
