67	
68	    thumbnailRequest =
69	        GlideApp.with(this).asDrawable().centerCrop().override(Api.SQUARE_THUMB_SIZE);
70	
71	    preloadRequest = thumbnail ? thumbnailRequest.clone().priority(Priority.HIGH) : fullRequest;
72	
