74	
75	    final int gridMargin = getResources().getDimensionPixelOffset(R.dimen.grid_margin);
76	    int spanCount = getResources().getDisplayMetrics().widthPixels / (photoSize + (2 * gridMargin));
77	    grid = result.findViewById(R.id.flickr_photo_grid);
78	    layoutManager = new GridLayoutManager(getActivity(), spanCount);
