3	import java.util.ArrayList;
4	import java.util.List;
5	import org.json.JSONArray;
6	import org.json.JSONException;
7	import org.json.JSONObject;
8	
9	/**
10	 * Parses a list of {@link Photo} objects from a Flickr API response string containing JSON data.
11	 */
12	final class PhotoJsonStringParser {
13	  private static final int FLICKR_API_PREFIX_LENGTH = 14;
14	
15	  List<Photo> parse(String response) throws JSONException {
16	    JSONObject searchResults =
17	        new JSONObject(response.substring(FLICKR_API_PREFIX_LENGTH, response.length() - 1));
18	    JSONArray photos = searchResults.getJSONObject("photos").getJSONArray("photo");
19	    List<Photo> results = new ArrayList<>(photos.length());
20	    for (int i = 0, size = photos.length(); i < size; i++) {
21	      results.add(new Photo(photos.getJSONObject(i)));
22	    }
23	
24	    return results;
25	  }
26	}
