69	    Log.w(TAG, "cycle: current=" + curr);
70	    ImageView.ScaleType[] all = ImageView.ScaleType.values();
71	    int nextOrdinal = (curr.ordinal() + 1) % all.length;
72	    ImageView.ScaleType next = all[nextOrdinal];
