19	import com.bumptech.glide.request.target.Target;
20	import com.bumptech.glide.util.Preconditions;
21	
22	/**
23	 * An activity that demonstrates loading photos using {@link
24	 * com.bumptech.glide.load.data.StreamLocalUriFetcher content uris} through Glide. It works by
25	 * making the user to choose a contact when presses a button, and after he chooses a contact with
26	 * photo, We try to load both a high res image and thumbnail image of that contact with various
27	 * Uris.
28	 */
29	public class MainActivity extends Activity {
30	  private static final int REQUEST_CONTACT = 1;
31	  private static final int READ_CONTACTS = 0;
32	
33	  private ImageView imageViewContact;
34	  private ImageView imageViewLookup;
35	  private ImageView imageViewPhoto;
36	  private ImageView imageViewDisplayPhoto;
37	  private EditText numberEntry;
38	
39	  @Override
40	  protected void onCreate(Bundle savedInstanceState) {
41	    super.onCreate(savedInstanceState);
42	    setContentView(R.layout.activity_main);
43	
44	    imageViewContact = findViewById(R.id.image_contact);
45	    imageViewLookup = findViewById(R.id.image_lookup);
46	    imageViewPhoto = findViewById(R.id.image_photo);
47	    imageViewDisplayPhoto = findViewById(R.id.image_display_photo);
48	    numberEntry = findViewById(R.id.number_entry);
49	    // Make sure that user gives application required permissions
50	    if (ContextCompat.checkSelfPermission(getApplication(), Manifest.permission.READ_CONTACTS)
51	        != PackageManager.PERMISSION_GRANTED) {
52	      // No explanation needed, we can request the permission.
53	      ActivityCompat.requestPermissions(
54	          this, new String[] {Manifest.permission.READ_CONTACTS}, READ_CONTACTS);
55	    }
56	
57	    findViewById(R.id.button_pick_contact)
58	        .setOnClickListener(
59	            new View.OnClickListener() {
60	              @Override
61	              public void onClick(View v) {
62	                Intent intent = new Intent(Intent.ACTION_PICK, Contacts.CONTENT_URI);
63	                startActivityForResult(intent, REQUEST_CONTACT);
64	              }
65	            });
66	
67	    findViewById(R.id.button_find)
68	        .setOnClickListener(
69	            new View.OnClickListener() {
70	              @Override
71	              public void onClick(View v) {
72	                Uri uri =
73	                    Uri.withAppendedPath(
74	                        ContactsContract.PhoneLookup.CONTENT_FILTER_URI,
75	                        Uri.encode(numberEntry.getText().toString()));
76	                GlideApp.with(MainActivity.this)
77	                    .load(uri)
78	                    .override(Target.SIZE_ORIGINAL)
79	                    .into(imageViewLookup);
80	              }
81	            });
82	  }
83	
84	  @Override
85	  protected void onActivityResult(int requestCode, int resultCode, Intent data) {
86	    if (requestCode == REQUEST_CONTACT && resultCode == RESULT_OK) {
87	      Uri uri = Preconditions.checkNotNull(data.getData());
88	      final Cursor cursor = getContentResolver().query(uri, null, null, null, null);
89	      try {
90	        if (cursor != null && cursor.moveToFirst()) {
91	          final long contactId = cursor.getLong(cursor.getColumnIndex(Contacts._ID));
92	          showContact(contactId);
93	        }
94	      } finally {
95	        if (cursor != null) {
96	          cursor.close();
97	        }
98	      }
99	      return;
100	    }
101	    super.onActivityResult(requestCode, resultCode, data);
102	  }
103	
104	  private void showContact(long id) {
105	    GlideRequests glideRequests = GlideApp.with(this);
106	    RequestOptions originalSize = new RequestOptions().override(Target.SIZE_ORIGINAL);
107	
108	    Uri contactUri = ContentUris.withAppendedId(Contacts.CONTENT_URI, id);
109	    glideRequests.load(contactUri).apply(originalSize).into(imageViewContact);
110	
111	    Uri lookupUri = Contacts.getLookupUri(getContentResolver(), contactUri);
112	    glideRequests.load(lookupUri).apply(originalSize).into(imageViewLookup);
113	
114	    Uri photoUri = Uri.withAppendedPath(contactUri, Contacts.Photo.CONTENT_DIRECTORY);
115	    glideRequests.load(photoUri).apply(originalSize).into(imageViewPhoto);
116	
117	    Uri displayPhotoUri = Uri.withAppendedPath(contactUri, Contacts.Photo.DISPLAY_PHOTO);
118	    glideRequests.load(displayPhotoUri).apply(originalSize).into(imageViewDisplayPhoto);
119	  }
120	}
