4	import androidx.annotation.NonNull;
5	import com.bumptech.glide.load.Options;
6	import com.bumptech.glide.load.model.GlideUrl;
7	import com.bumptech.glide.load.model.ModelLoader;
8	import com.bumptech.glide.load.model.ModelLoaderFactory;
9	import com.bumptech.glide.load.model.MultiModelLoaderFactory;
10	import com.bumptech.glide.load.model.stream.BaseGlideUrlLoader;
11	import com.bumptech.glide.samples.giphy.Api.GifResult;
12	import java.io.InputStream;
13	
14	/**
15	 * A model loader that translates a POJO mirroring a JSON object representing a single image from
16	 * Giphy's api into an {@link java.io.InputStream} that can be decoded into an {@link
17	 * android.graphics.drawable.Drawable}.
18	 */
19	public final class GiphyModelLoader extends BaseGlideUrlLoader<Api.GifResult> {
20	
21	  @Override
22	  public boolean handles(@NonNull Api.GifResult model) {
23	    return true;
24	  }
25	
26	  private GiphyModelLoader(ModelLoader<GlideUrl, InputStream> urlLoader) {
27	    super(urlLoader);
28	  }
29	
30	  @Override
31	  protected String getUrl(Api.GifResult model, int width, int height, Options options) {
32	    Api.GifImage fixedHeight = model.images.fixed_height;
33	    int fixedHeightDifference = getDifference(fixedHeight, width, height);
34	    Api.GifImage fixedWidth = model.images.fixed_width;
35	    int fixedWidthDifference = getDifference(fixedWidth, width, height);
36	    if (fixedHeightDifference < fixedWidthDifference && !TextUtils.isEmpty(fixedHeight.url)) {
37	      return fixedHeight.url;
38	    } else if (!TextUtils.isEmpty(fixedWidth.url)) {
39	      return fixedWidth.url;
40	    } else if (!TextUtils.isEmpty(model.images.original.url)) {
41	      return model.images.original.url;
42	    } else {
43	      return null;
44	    }
45	  }
46	
47	  private static int getDifference(Api.GifImage gifImage, int width, int height) {
48	    return Math.abs(width - gifImage.width) + Math.abs(height - gifImage.height);
49	  }
50	
51	  /** The default factory for {@link com.bumptech.glide.samples.giphy.GiphyModelLoader}s. */
52	  public static final class Factory implements ModelLoaderFactory<GifResult, InputStream> {
53	    @NonNull
54	    @Override
55	    public ModelLoader<Api.GifResult, InputStream> build(MultiModelLoaderFactory multiFactory) {
56	      return new GiphyModelLoader(multiFactory.build(GlideUrl.class, InputStream.class));
57	    }
58	
59	    @Override
60	    public void teardown() {
61	      // Do nothing.
62	    }
63	  }
64	}
